import sys

def main():
    data = sys.stdin.read().split('\n')
    idx = 0
    def nextline():
        nonlocal idx
        while idx < len(data):
            line = data[idx]
            idx += 1
            return line.strip()
        return None

    first = nextline()
    while first is not None and first == '':
        first = nextline()
    if first is None:
        print("ERR")
        return
    try:
        k = int(first)
    except ValueError:
        print("ERR")
        return

    prog = []
    for _ in range(k):
        raw = nextline()
        if raw is None:
            prog.append(("BAD",))
            continue
        line = raw.strip()
        if line == '':
            prog.append(("BAD",))
            continue
        parts = line.split()
        op = parts[0].upper()
        arg = None
        if op == "PUSH":
            if len(parts) == 2:
                try:
                    arg = int(parts[1])
                except ValueError:
                    op = "BAD"
            else:
                op = "BAD"
        elif op == "JNZ":
            if len(parts) == 2:
                try:
                    arg = int(parts[1])
                except ValueError:
                    op = "BAD"
            else:
                op = "BAD"
        elif op in ("POP", "ADD", "SUB", "MUL", "DUP", "SWAP", "PRINT", "HALT"):
            if len(parts) != 1:
                op = "BAD"
        else:
            op = "BAD"
        prog.append((op, arg))

    stack = []
    out = []
    pc = 0
    steps = 0

    def pop():
        if not stack:
            raise IndexError
        v = stack.pop()
        return v

    while True:
        if steps >= 10000:
            print("ERR")
            return
        steps += 1
        if pc < 0 or pc >= len(prog):
            print("ERR")
            return
        ins = prog[pc]
        op = ins[0]
        if op == "PUSH":
            stack.append(ins[1])
            pc += 1
        elif op == "POP":
            pop()
            pc += 1
        elif op == "ADD":
            a = pop(); b = pop()
            stack.append(b + a)
            pc += 1
        elif op == "SUB":
            a = pop(); b = pop()
            stack.append(b - a)
            pc += 1
        elif op == "MUL":
            a = pop(); b = pop()
            stack.append(b * a)
            pc += 1
        elif op == "DUP":
            if not stack:
                print("ERR")
                return
            stack.append(stack[-1])
            pc += 1
        elif op == "SWAP":
            if len(stack) < 2:
                print("ERR")
                return
            stack[-1], stack[-2] = stack[-2], stack[-1]
            pc += 1
        elif op == "PRINT":
            out.append(str(pop()))
            pc += 1
        elif op == "JNZ":
            v = pop()
            if v != 0:
                target = ins[1]
                if target < 0 or target >= len(prog):
                    print("ERR")
                    return
                pc = target
            else:
                pc += 1
        elif op == "HALT":
            sys.stdout.write('\n'.join(out) + ('\n' if out else ''))
            return
        else:
            print("ERR")
            return

main()
